/**
 * Shared constants for the SFCC-11 cart build. Same role as theme/components/footerShared.ts /
 * headerShared.ts — see .claude/rules/overrideStyling.md's "Cross-file shared values" section:
 * a value needed by more than one file goes here once, imported everywhere it's needed, so two
 * call sites can't independently retype the same number and silently drift apart. Placed
 * alongside `ui-kits/` (rather than `theme/components/`, where footerShared.ts/headerShared.ts
 * live) because this cart build's first consumer is a component-local recipe co-located under
 * `ui-kits/molecules/`, not a `theme/components/`-resident recipe — later commits in this same
 * build may add more cart-item constants here, but that is not yet built and is not asserted as
 * done by this comment.
 */

// Icon-button disabled opacity for the cart quantity stepper (ZimmQuantityStepper, SFCC-271).
// Intentionally the SAME numeric value as zimmButton.css.ts's own OPACITY_ICON_DISABLED (0.4,
// see that file's `icon`/`iconInverse` variants) — not imported from there, because that file is
// a Tier 2 recipe this build step does not touch, and a constant needed by a sibling recipe
// (zimmQuantityStepper.css.ts) plus this component's own tests should not have to reach into an
// unrelated atom's styling module for an unrelated number. Kept here as its own named constant,
// deliberately equal, so both places that dim something to "the disabled look" (ZimmButton's own
// icon variant, applied automatically once ariaDisabled is passed, and this stepper's own value
// display, which is not a ZimmButton and so has no such variant of its own) render at the
// identical opacity instead of two independently-authored numbers that only start out matching.
// Per conventions.md > "No magic numbers or strings" — a named constant, not an inline literal.
export const OPACITY_ICON_DISABLED = 0.4;

